function renderModule(m, idx){
  const MY=myMods();
  const wrap=h("div",{class:"wrap"});
  const head=h("header",{class:"mod-head"});
  head.append(h("span",{class:"mono eyebrow"},`Module ${idx+1} of ${MY.length}`), h("h1",{},esc(m.title)), h("p",{},esc(m.blurb)));
  const forms=[...new Set(m.blocks.filter(b=>b.k==="set").map(b=>P[b.passage].form))];
  head.append(h("div",{class:"meta"},`<span class="chip">${esc(m.time)}</span>`+forms.map(f=>`<span class="chip form">${esc(f)}</span>`).join("")));
  wrap.append(head);
  let n=0;
  m.blocks.forEach(b=>{
    if(b.k==="lesson"){ const l=h("section",{class:"lesson"}); l.append(h("h2",{},esc(b.title))); const c=h("div",{style:"display:flex;flex-direction:column;gap:12px"},b.html); l.append(c); wrap.append(l); }
    else if(b.k==="label"){ wrap.append(h("div",{class:"section-label"},`<span class="mono">${esc(b.text)}</span>`)); }
    else if(b.k==="q"){ wrap.append(renderQ(b,++n)); }
    else if(b.k==="set"){ const s=h("div",{class:"set"}); s.append(renderPassage(b.passage)); const col=h("div",{class:"qcol"}); b.qs.forEach(q=>col.append(renderQ(q,++n))); s.append(col); wrap.append(s); }
    else if(b.k==="write"){ wrap.append(renderWrite(b)); }
    else if(b.k==="results"){ wrap.append(renderResults(m)); }
  });
  const pg=h("nav",{class:"pager","aria-label":"Module navigation"});
  pg.append(h("a",{href: idx>0?"#"+MY[idx-1].id:"#home"},"← "+(idx>0?esc(MY[idx-1].title):"Overview")));
  pg.append(h("a",{href: idx<MY.length-1?"#"+MY[idx+1].id:"#home"},(idx<MY.length-1?esc(MY[idx+1].title):"Back to overview")+" →"));
  wrap.append(pg);
  return wrap;
}

function go(hsh){ if((location.hash.slice(1)||"home")===hsh) route(); else location.hash=hsh; }
function route(){
  const id=location.hash.slice(1)||"home";
  main.innerHTML="";
  if(!dbReady){ main.append(h("div",{class:"wrap narrow"},'<p class="muted">Connecting…</p>')); }
  else if(TUTOR){ main.append(id.startsWith("student-")?renderStudent(id.slice(8)):renderGradebook()); }
  else if(!ME){ main.append(renderLogin()); }
  else { const mm=myMods(); const idx=mm.findIndex(m=>m.id===id); main.append(idx>=0?renderModule(mm[idx],idx):renderHome()); paintGrades(); }
  updateNav();
  $("#rail").classList.remove("open"); $("#menuBtn").setAttribute("aria-expanded","false");
  window.scrollTo(0,0);
}
window.addEventListener("hashchange",route);
$("#menuBtn").onclick=()=>{ const o=$("#rail").classList.toggle("open"); $("#menuBtn").setAttribute("aria-expanded",String(o)); };


// ---------- SIGN-IN, GRADES, GRADEBOOK ----------
// backend.js (a module) hands over the database once it has loaded. If it has not
// loaded within 8 seconds, the page falls back to saving on this device only.
const dbP = new Promise(res=>{ window.__twBackendReady=res; setTimeout(()=>res(null), 8000); });
function slug(n){ return n.toLowerCase().normalize("NFD").replace(/[̀-ͯ]/g,"").replace(/[^a-z0-9]+/g,"-").replace(/^-|-$/g,"").slice(0,40)||"student"; }
function when(iso){ try{ return new Date(iso).toLocaleString([], {month:"short",day:"numeric",hour:"numeric",minute:"2-digit"}); }catch(e){ return ""; } }
function signInProblem(e){ const c=(e&&e.code)||""; return c==="too-many-tries"?"Too many wrong tries. Wait a few minutes, then try again.":c==="network"?"Couldn’t connect. Check your connection and try again.":null; }

// Load a signed-in student's saved work and make them the current student.
async function enterAs(who){
  const d=await DB.doc("progress/"+who.id).get();
  S=d.exists?Object.assign(blank(),JSON.parse(JSON.stringify(d.data()))):blank(); delete S.name; delete S.updatedAt;
  ME={id:who.id,name:who.name}; MINE=Array.isArray(who.modules)?who.modules:null; setSaveNote(""); watchGrades();
}

function renderLogin(){
  const wrap=h("div",{class:"wrap narrow"});
  wrap.append(h("header",{class:"mod-head"},`<span class="mono eyebrow">TutorWise · Literacy</span><h1>Who’s working today?</h1><p>Enter your first name and your PIN.</p>`));
  const card=h("section",{class:"lesson signin"}); wrap.append(card);
  const foot=h("p",{class:"muted",style:"font-size:.9rem"}); const tbtn=h("button",{class:"linkbtn",type:"button"},"Tutor sign-in"); foot.append(tbtn); wrap.append(foot);
  tbtn.onclick=()=>tutorStep(card);
  if(!DB){
    tbtn.hidden=true;
    card.append(h("p",{class:"note-warn"},"Sign-in isn’t connected here, so work saves on this device only and won’t reach the gradebook."));
    const lab=h("label",{for:"offName"},"Your first name"); const inp=h("input",{id:"offName",type:"text",class:"field",autocomplete:"off"}); const b=h("button",{class:"btn",type:"button"},"Start");
    b.onclick=()=>{ const n=inp.value.trim(); if(!n) return; ME={id:slug(n),name:n}; try{ const raw=localStorage.getItem(KEY+":"+ME.id); S=raw?Object.assign(blank(),JSON.parse(raw)):blank(); }catch(e){ S=blank(); } go("home"); };
    const r=h("div",{class:"q-actions"}); r.append(b); card.append(lab,inp,r);
    return wrap;
  }
  const nLab=h("label",{for:"nameIn"},"Your first name"); const nIn=h("input",{id:"nameIn",type:"text",class:"field",autocomplete:"username",autocapitalize:"words",spellcheck:"false",maxlength:"40"});
  const pLab=h("label",{for:"pinIn"},"Your PIN"); const pIn=h("input",{id:"pinIn",type:"password",inputmode:"numeric",autocomplete:"current-password",class:"field pin",maxlength:"8"});
  const b=h("button",{class:"btn",type:"button"},"Sign in"); const msg=h("p",{class:"err",role:"alert"}); const r=h("div",{class:"q-actions"}); r.append(b);
  card.append(nLab,nIn,pLab,pIn,r,msg);
  const submit=async()=>{
    const n=nIn.value.trim(), v=pIn.value.trim(); msg.textContent="";
    if(!n||!v){ msg.textContent="Type your first name and your PIN."; return; }
    b.disabled=true; b.textContent="Signing in…";
    try{ const who=await DB.signInStudent(n,v); await enterAs(who); go("home"); }
    catch(e){ msg.textContent=signInProblem(e)||"That name and PIN don’t match. Try again, or ask your tutor."; b.disabled=false; b.textContent="Sign in"; pIn.select(); }
  };
  b.onclick=submit; pIn.onkeydown=e=>{ if(e.key==="Enter") submit(); }; nIn.onkeydown=e=>{ if(e.key==="Enter") pIn.focus(); };
  return wrap;
}

function tutorStep(card){
  card.innerHTML="";
  card.append(h("h2",{},"Tutor sign-in"));
  let firstRun=false, checked=false;
  const lab=h("label",{for:"tutIn"},"Tutor password");
  const inp=h("input",{id:"tutIn",type:"password",autocomplete:"current-password",class:"field",maxlength:"64"});
  const b=h("button",{class:"btn",type:"button"},"Sign in"); const back=h("button",{class:"btn ghost",type:"button"},"Back");
  const msg=h("p",{class:"err",role:"alert"}); const r=h("div",{class:"q-actions"}); r.append(b,back);
  card.append(lab,inp,r,msg); setTimeout(()=>inp.focus(),0);
  back.onclick=()=>route();
  DB.tutorExists().then(ex=>{ checked=true; if(!ex){ firstRun=true; lab.textContent="Create your tutor password (at least 8 characters)"; inp.setAttribute("autocomplete","new-password"); b.textContent="Create password and sign in"; } })
    .catch(()=>{ msg.textContent="Couldn’t reach the gradebook. Check your connection."; });
  const submit=async()=>{
    const v=inp.value; msg.textContent="";
    if(!checked){ msg.textContent="Still checking. Try again in a second."; return; }
    if(firstRun&&v.length<8){ msg.textContent="Use at least 8 characters."; return; }
    if(!v) return;
    b.disabled=true;
    try{ if(firstRun) await DB.tutorCreate(v); else await DB.tutorSignIn(v); TUTOR=true; go("gradebook"); }
    catch(e){ msg.textContent=signInProblem(e)||(firstRun?"Couldn’t create the tutor sign-in. Reload the page and try again.":"That password doesn’t match."); b.disabled=false; inp.select(); }
  };
  b.onclick=submit; inp.onkeydown=e=>{ if(e.key==="Enter") submit(); };
}

function watchGrades(){
  if(unsubGrades) unsubGrades(); GRADES={};
  if(!DB) return;
  unsubGrades=DB.doc("grades/"+ME.id).onSnapshot(s=>{ GRADES=(s.exists&&(s.data()||{}).items)||{}; paintGrades(); }, ()=>{});
}
function gradeHTML(g){
  return `<h4>Tutor feedback</h4><div class="lv">${g.content?`<span class="pill strong">Content · Level ${esc(g.content)}</span>`:""}${g.conventions?`<span class="pill strong">Conventions · Level ${esc(g.conventions)}</span>`:""}</div>${g.comment?`<p>${esc(g.comment).replace(/\n/g,"<br>")}</p>`:""}<p class="note">Marked ${esc(when(g.at))}</p>`;
}
function paintGrades(){ document.querySelectorAll("[data-grade]").forEach(el=>{ const g=GRADES[el.dataset.grade]; el.hidden=!g; if(g) el.innerHTML=gradeHTML(g); }); }

function skillRow(label, c, t){ const row=h("div",{class:"skillrow"}); row.append(h("span",{},esc(label)), h("div",{class:"bar"},`<i style="width:${t?Math.round(c/t*100):0}%"></i>`), h("span",{class:"v"},`${c}/${t}`)); return row; }

function renderGradebook(){
  const wrap=h("div",{class:"wrap"});
  wrap.append(h("header",{class:"mod-head"},`<span class="mono eyebrow">Tutor view</span><h1>Gradebook</h1><p>Selected-response questions mark themselves. Open a student to read their writing and give it a grade.</p>`));
  const bar=h("div",{class:"q-actions"}); const rf=h("button",{class:"btn ghost",type:"button"},"Refresh"); bar.append(rf, h("a",{class:"btn ghost",href:"tutor/"},"Reading lessons: tracking and marking")); wrap.append(bar);
  const tbl=h("div",{class:"tablewrap"},'<p class="muted">Loading…</p>'); wrap.append(tbl);
  const loadTable=async()=>{
    try{
      const [st,pr]=await Promise.all([DB.collection("students").get(), DB.collection("progress").get()]);
      const PR={}; pr.docs.forEach(d=>PR[d.id]=d.data());
      if(st.empty){ tbl.innerHTML='<p class="muted">No students yet. Add one below.</p>'; return; }
      const rows=st.docs.map(d=>{ const s=d.data()||{}, x=Object.assign(blank(),PR[d.id]||{});
        const mine=Array.isArray(s.modules)?s.modules:null;
        const cells=MODULES.map(m=>{ if(mine&&!mine.includes(m.id)) return `<td class="num"><small>not given</small></td>`; const p=modProgress(m,x); return `<td class="num">${p.qn?`${p.correct}/${p.qn}`:"—"}<small>${p.done}/${p.total} done</small></td>`; }).join("");
        return `<tr><td><a href="#student-${esc(d.id)}"><b>${esc(s.name||d.id)}</b></a></td>${cells}<td><small>${x.updatedAt?esc(when(x.updatedAt)):"Not started"}</small></td></tr>`; }).join("");
      tbl.innerHTML=`<table class="facts gb"><tr><th>Student</th>${MODULES.map((m,i)=>`<th title="${esc(m.title)}">M${i+1}</th>`).join("")}<th>Last active</th></tr>${rows}</table><p class="muted" style="font-size:.85rem;margin-top:8px">Each cell shows correct answers, then activities done. M1 Know the Test · M2 Narratives &amp; Dialogues · M3 Information &amp; News · M4 Conventions · M5 Opinion Essay · M6 Practice Test.</p>`;
    }catch(e){ tbl.innerHTML='<p class="muted">Couldn’t load the gradebook. Check your connection, then press Refresh.</p>'; }
  };
  rf.onclick=loadTable;
  const add=h("section",{class:"lesson"}); add.append(h("h2",{},"Add a student"));
  add.append(h("div",{class:"planner"},`<label for="nsName">First name<input id="nsName" type="text" autocomplete="off"></label><label for="nsPin">PIN (4 to 8 digits)<input id="nsPin" type="text" inputmode="numeric" maxlength="8" autocomplete="off"></label>`));
  const ab=h("button",{class:"btn",type:"button"},"Add student"); const am=h("span",{class:"muted",role:"status"}); const ar=h("div",{class:"q-actions"}); ar.append(ab,am); add.append(ar);
  add.append(h("p",{class:"muted",style:"font-size:.88rem"},"Adding a name that already exists gives that student a new PIN and keeps their work. PINs can’t be looked up later, so note them down. A new student starts with all six OSSLT modules; open the student to change which modules they get. Work in the reading lessons is tied to the PIN it was done under and does not carry over to a new PIN."));
  ab.onclick=async()=>{ const n=$("#nsName").value.trim(), p=$("#nsPin").value.trim(); if(!n||!/^\d{4,8}$/.test(p)){ am.textContent="Enter a name and a PIN of 4 to 8 digits."; return; } ab.disabled=true; try{ await DB.addStudent(n,p,MODULES.map(m=>m.id)); am.textContent=`Added ${n}. They can sign in now.`; $("#nsName").value=""; $("#nsPin").value=""; loadTable(); }catch(e){ am.textContent="Couldn’t add the student. Try again."; } ab.disabled=false; };
  wrap.append(add);
  loadTable();
  return wrap;
}

function renderStudent(sid){
  const wrap=h("div",{class:"wrap"}); wrap.append(h("p",{},`<a href="#gradebook">← Gradebook</a>`));
  const body=h("div",{style:"display:flex;flex-direction:column;gap:22px"},'<p class="muted">Loading…</p>'); wrap.append(body);
  Promise.all([DB.doc("students/"+sid).get(), DB.doc("progress/"+sid).get(), DB.doc("grades/"+sid).get()]).then(([s,p,g])=>{
    body.innerHTML="";
    const name=s.exists?((s.data()||{}).name||sid):sid; const X=Object.assign(blank(), p.exists?JSON.parse(JSON.stringify(p.data())):{}); const G=(g.exists&&(g.data()||{}).items)||{};
    body.append(h("header",{class:"mod-head"},`<span class="mono eyebrow">Student</span><h1>${esc(name)}</h1><p>${X.updatedAt?"Last active "+esc(when(X.updatedAt)):"Hasn’t started yet."}</p>`));
    const sd=s.exists?(s.data()||{}):{};
    const given=new Set(Array.isArray(sd.modules)?sd.modules:MODULES.map(m=>m.id));
    const as=h("section",{class:"lesson"}); as.append(h("h2",{},"Modules for this student"), h("p",{class:"muted"},"Tick the modules "+esc(name)+" should see when signed in."));
    const aul=h("ul",{class:"checklist"});
    const opt=(id,label)=>{ const cid="as-"+id; const li=h("li"); const lab=h("label",{for:cid}); const cb=h("input",{type:"checkbox",id:cid,value:id}); cb.checked=given.has(id); lab.append(cb,h("span",{},esc(label))); li.append(lab); aul.append(li); };
    MODULES.forEach((m,i)=>opt(m.id,`OSSLT M${i+1} · ${m.title}`));
    READING.forEach(r=>opt(r.id,`Reading skills ${r.number} · ${r.title}`));
    as.append(aul);
    const asv=h("button",{class:"btn",type:"button"},"Save modules"); const asm=h("span",{class:"muted",role:"status"}); const asr=h("div",{class:"q-actions"}); asr.append(asv,asm);
    if(READING.some(r=>given.has(r.id))&&sd.uid) asr.append(h("a",{class:"btn ghost",href:"tutor/?s="+encodeURIComponent(sd.uid)},"Reading lessons tracking"));
    as.append(asr);
    asv.onclick=async()=>{ asv.disabled=true; asm.textContent="Saving…"; try{ await DB.setStudentModules(sid,[...aul.querySelectorAll("input:checked")].map(c=>c.value)); asm.textContent="Saved. "+name+" sees these modules at their next sign-in."; }catch(e){ asm.textContent="Couldn’t save. Try again."; } asv.disabled=false; };
    body.append(as);
    const ms=h("section",{class:"lesson"}); ms.append(h("h2",{},"Selected-response results"));
    MODULES.forEach((m,i)=>{ const pr=modProgress(m,X); if(pr.qn) ms.append(skillRow(`M${i+1} · ${m.title}`, pr.correct, pr.qn)); });
    const by={}; MODULES.forEach(m=>questionsOf(m).forEach(q=>{ const a=X.ans[q.id]; if(!a||!a.checked) return; const k=by[q.skill]||(by[q.skill]={c:0,t:0}); k.t++; if(a.ok) k.c++; }));
    const sk=Object.entries(by).sort((a,b)=>a[1].c/a[1].t-b[1].c/b[1].t);
    if(sk.length){ ms.append(h("h3",{style:"margin-top:8px;font-size:1.05rem"},"By skill, weakest first (answered questions only)")); sk.forEach(([k,v])=>ms.append(skillRow(k,v.c,v.t))); }
    else ms.append(h("p",{class:"muted"},"No questions checked yet."));
    body.append(ms);
    body.append(h("div",{class:"section-label"},'<span class="mono">Written responses</span>'));
    MODULES.forEach((m,i)=>writesOf(m).forEach(w=>{
      const txt=X.w[w.id]||""; const gg=G[w.id]||{};
      const card=h("section",{class:"write"});
      card.append(h("div",{class:"q-top"},`<h3>M${i+1} · ${esc(w.title)}</h3><span class="q-type">${words(txt)} words</span>`));
      card.append(h("p",{class:"prompt"},esc(w.prompt)));
      card.append(h("div",{class:"response"}, txt.trim()?esc(txt).replace(/\n/g,"<br>"):'<span class="muted">Not written yet.</span>'));
      const lv=(id,label,val)=>`<label for="${id}">${label}<select id="${id}"><option value="">Not graded</option>${[1,2,3,4].map(n=>`<option value="${n}" ${String(val)===String(n)?"selected":""}>Level ${n}</option>`).join("")}</select></label>`;
      card.append(h("div",{class:"planner"}, lv(w.id+"-gc","Content and organization",gg.content)+lv(w.id+"-gv","Conventions",gg.conventions)));
      const ta=h("textarea",{id:w.id+"-gm",placeholder:"Comment for the student",style:"min-height:90px","aria-label":"Comment for the student"}); ta.value=gg.comment||""; card.append(ta);
      const sv=h("button",{class:"btn",type:"button"},"Save grade"); const sm=h("span",{class:"muted",role:"status"},gg.at?"Last saved "+esc(when(gg.at)):""); const r=h("div",{class:"q-actions"}); r.append(sv,sm); card.append(r);
      sv.onclick=async()=>{ sv.disabled=true; sm.textContent="Saving…";
        const item={content:$("#"+w.id+"-gc").value, conventions:$("#"+w.id+"-gv").value, comment:ta.value.trim(), at:new Date().toISOString()};
        try{ const ref=DB.doc("grades/"+sid); const cur=await ref.get(); const items=Object.assign({}, (cur.exists&&(cur.data()||{}).items)||{}); items[w.id]=item; await ref.set({items}); sm.textContent="Saved. The student sees it on their page."; }
        catch(e){ sm.textContent="Couldn’t save. Try again."; }
        sv.disabled=false; };
      body.append(card);
    }));
  }).catch(()=>{ body.innerHTML='<p class="muted">Couldn’t load this student. Check your connection and reload.</p>'; });
  return wrap;
}

$("#signOut").onclick=async()=>{
  clearTimeout(saveT);
  while(SV.busy) await new Promise(r=>setTimeout(r,100));
  if(ME) await flush();
  if(unsubGrades){ unsubGrades(); unsubGrades=null; }
  if(DB&&DB.signOut){ try{ await DB.signOut(); }catch(e){} }
  ME=null; MINE=null; TUTOR=false; S=blank(); GRADES={}; setSaveNote(""); go("home");
};
window.addEventListener("pagehide",()=>{ if(ME) flush(); });

(async function initApp(){
  route(); DB=await dbP;
  // Still signed in on this device from last time? Go straight in.
  if(DB&&DB.readingModules){ try{ READING=await DB.readingModules(); }catch(e){} }
  if(DB){ try{ const who=await DB.current(); if(who&&who.tutor) TUTOR=true; else if(who) await enterAs(who); }catch(e){} }
  dbReady=true; route();
})();
